            { id = 231, name = "Gnomeregan", continent = 1415, map = "Gnomer", floor = 1, area = 721, button = 608202, lore = 608241, bg = 608163,
              desc = "Built deep within the mountains of Dun Morogh, the wondrous city of Gnomeregan was a testament to the gnomes' intelligence and industry. But when the capital was invaded by troggs, the gnomish high tinker was betrayed by his advisor Sicco Thermaplugg. As a result, Gnomeregan was irradiated, and most of its inhabitants slain. The surviving gnomes fled, vowing to return someday and retake their home.",
              encounters = {
                { id = 7361, name = "Grubbis", portrait = 607628,
                  desc = "The radioactive gas that flooded the city was meant to anger the troggs and kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, however, reacted oddly to the substance: Grubbis grew. And grew. It was a side effect that Sicco had not anticipated, but he's never been one to waste valuable (and dangerous) resources. This giant trogg now patrols the tunnels of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas leaks, tasty fungi, and even tastier intruders.",
                  creatures = { { name = "Grubbis", display = 6533, dist = 2.8, eye = 0.47 } },
                  loot = { 9445, 8.8 },
                  sections = {
                    { id = 4690, title = "Strike", icon = 132282, text = "Grubbis inflicts Physical damage to his current target." },
                    { id = 6476, title = "Chomper", display = 4906, dist = 7.5, eye = 0.52, text = "Chomper fights alongside Grubbis." },
                  },
                },
                { id = 7079, name = "Viscous Fallout", portrait = 607808,
                  desc = "The formerly robust and elegantly complex waterways of Gnomeregan are now an irradiated mess filled with toxic slime. A lone water elemental who had dwelt in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form. It currently wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal.",
                  creatures = { { name = "Viscous Fallout", display = 5497, dist = 4, eye = 1.03 } },
                  loot = { 9454, 60.8, 9452, 18.8, 9453, 17.5 },
                  sections = {
                    { id = 4691, title = "Toxic Volley", icon = 136016, flags = 512, text = "Viscous Fallout unleashes a volley of toxin, inflicting 56 Nature damage to all players within 45 yards and 7 Nature damage every 3 seconds for 15 sec." },
                  },
                },
                { id = 6235, name = "Electrocutioner 6000", portrait = 607594,
                  desc = "Mekgineer Thermaplugg is not a patient gnome. Rather than putting his inventions through a battery of tests to determine their safety and effectiveness, he rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt at harnessing electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom \"Sizzlepants\" Crankle, the only soldier to survive piloting the Electrocutioner, is now something of a hero among the leper gnomes.",
                  creatures = { { name = "Electrocutioner 6000", display = 6915, dist = 7.9, eye = 1 } },
                  loot = { 6893, 79.4, 9448, 41.2, 9447, 31.1, 9446, 16.2 },
                  sections = {
                    { id = 4692, title = "Megavolt", icon = 136015, flags = 64, text = "Electrocutioner 6000 inflicts Nature damage to all players in front of him." },
                    { id = 4693, title = "Shock", icon = 136115, text = "Electrocutioner 6000 throws a bolt of lightning at his current target, inflicting Nature damage." },
                    { id = 4694, title = "Chain Bolt", icon = 136015, flags = 64, text = "Electrocutioner 6000 strikes his current target with a lightning bolt that arcs to 3 nearby targets, inflicting Nature damage to each target." },
                  },
                },
                { id = 6229, name = "Crowd Pummeler 9-60", portrait = 607572,
                  desc = "In Gnomeregan's heyday, inventors would compete for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot, and this earned him respect in the high tinker's court. Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version of the machine. He set his forgery loose, and the horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite (stolen) inventions.",
                  creatures = { { name = "Crowd Pummeler 9-60", display = 6774, dist = 4.8, eye = 0.8 } },
                  loot = { 9450, 65.3, 9449, 32.6 },
                  sections = {
                    { id = 4670, title = "Arcing Smash", icon = 132338, text = "Crowd Pummeler 9-60 lashes out in a vicious arc, inflicting Physical damage to players in front of it." },
                    { id = 4671, title = "Crowd Pummel", icon = 132938, text = "Crowd Pummeler 9-60 pummels players within 10 yards, inflicting Physical damage and interrupting spell casting for 5 sec." },
                    { id = 4672, title = "Trample", icon = 136063, text = "Crowd Pummeler 9-60 tramples players within 10 yards, inflicting Physical damage." },
                  },
                },
                { id = 7800, name = "Mekgineer Thermaplugg", portrait = 607714,
                  desc = "Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a malfunctioning iron fist. His subjects are numerous, vicious, and insane enough to defend their crazed king against any intrusion from the upper world. It is Thermaplugg's madness that makes him so dangerous; he possesses the cunning to destroy everything around him, with no thought for his own life. There is a reason that even the monsters of Gnomeregan fear him.",
                  creatures = { { name = "Mekgineer Thermaplugg", display = 6980, dist = 7.2, eye = 1.19 } },
                  loot = { 9461, 32.3, 9458, 31.8, 9459, 18.3, 9492, 9.5, 4411, 0.5, 4415, 0.5, 4413, 0.4, 7742, 0.3, 11828, 0 },
                  sections = {
                    { id = 4702, title = "Steam Blast", icon = 135831, flags = 64, text = "Mekgineer Thermaplugg blasts his current target with steam, inflicting Fire damage and knocking them back." },
                    { id = 4703, title = "Pound", icon = 132154, text = "Mekgineer Thermaplugg pounds his current target, inflicting Physical damage and disorienting them." },
                    { id = 4704, title = "Welding Beam", icon = 136050, flags = 64, text = "Mekgineer Thermplugg blasts his current target with a welding beam, inflicting 250 Nature damage." },
                    { id = 4700, title = "Walking Bomb", display = 6977, dist = 5.9, eye = 0.98, flags = 32, text = "Mekgineer Thermaplugg activates a nearby bomb assembly, causing it to periodically release Walking Bombs that attack a random player. Walking Bombs will continue to spawn until the red switch on the side of the assembly is activated.", sub = {
