            { id = 239, name = "Uldaman", continent = 1415, map = "Ulda", floor = 1, area = 1337, button = 608225, lore = 608264, bg = 608186,
              desc = "Uldaman is an ancient titan vault buried deep within the earth. It is said the titans sealed away a failed experiment there and then moved on to a new project, related to the genesis of the dwarves. Tales of a fabled treasure containing great knowledge have enticed would-be treasure hunters to dig deeper into the secrets of Uldaman, a task made perilous by the presence of stone defenders, savage troggs, Dark Iron invaders, and other dangers lurking in the lost city.",
              encounters = {
                { id = 6910, name = "Revelosh", portrait = 607757,
                  desc = "Some luminaries in Ironforge's prestigious Explorers' League have theorized an ancestral link between their people and the troggs, and pointed towards the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices. If that is true, the trogg known as Revelosh can be considered the trogg equivalent of an archaeologist, although any historically minded adventurers who encounter him would be more inclined to call him a thief.",
                  creatures = { { name = "Revelosh", display = 5945, dist = 2.8, eye = 0.47 } },
                  loot = { 7741, 40.2, 9389, 23.3, 9387, 22.7, 9390, 21.1, 9388, 21 },
                  sections = {
                    { id = 4820, title = "Chain Lightning", icon = 136015, flags = 64, text = "Revelosh strikes his target with a lightning bolt that arcs to nearby players, inflicting Nature damage to 3 targets." },
                    { id = 4821, title = "Lightning Bolt", icon = 136048, flags = 64, text = "Revelosh blasts his current target with lightning, inflicting Nature damage." },
                  },
                },
                { id = 6906, name = "The Lost Dwarves", portrait = 607550,
                  desc = "Seeking fame and, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.",
                  creatures = { { name = "The Lost Dwarves", display = 5710, dist = 2.4, eye = 0.4 } },
                  loot = { 9399, 87.6, 9400, 39.6, 9401, 9.3 },
                  sections = {
                    { id = 4869, title = "Baelog", text = "Baelog favors combat, attacking with his sword and bow.", sub = {
                        { id = 4870, title = "Strike", icon = 132282, text = "Baelog strikes his current target, inflicting Physical damage." },
                        { id = 4871, title = "Shoot", icon = 132222, text = "Baelog shoots a player, inflicting Physical damage." },
                    } },
                    { id = 4874, title = "Eric \"The Swift\"", text = "Eric favors speed, charging head-first into battle.", sub = {
                        { id = 4875, title = "Rushing Charge", icon = 132368, text = "Eric \"The Swift\" charges towards a player, increasing the damage of his next attack." },
                    } },
                    { id = 4872, title = "Olaf", text = "Olaf favors defense, blocking with his shield.", sub = {
                        { id = 4873, title = "Shield Slam", icon = 132357, text = "Olaf slams his target, inflicting Physical damage and stunning them for 2 sec." },
                    } },
                  },
                },
                { id = 7228, name = "Ironaya", portrait = 607664,
                  desc = "The titans did not construct the Uldaman complex directly, but utilized various servants to create its megalithic halls. The Pantheon entrusted the watcher Ironaya with overseeing the construction and maintenance of Uldaman, but as time passed, the once awe-inspiring vault fell to ruin. Within the map chamber, Ironaya has spent millennia in a form of stasis, analyzing the original master plan drawn up by Khaz'goroth and attempting to find a way to restore the complex to its original functionality.",
                  creatures = { { name = "Ironaya", display = 6089, dist = 11, eye = 1.83 } },
                  loot = { 9407, 37.7, 9409, 37.7, 9408, 20.5 },
                  sections = {
                    { id = 4876, title = "Arcing Smash", icon = 132338, text = "Ironaya lashes out in a vicious arc, inflicting Physical damage to all enemies in front of her." },
                    { id = 4877, title = "Knock Away", icon = 132939, text = "Ironaya inflicts Physical damage to her current target, knocking them away." },
                    { id = 4878, title = "War Stomp", icon = 132091, text = "Ironaya stomps, inflicting Physical damage to all enemies within 5 yards and stunning them for 5 sec." },
                  },
                },
                { id = 7206, name = "Ancient Stone Keeper", portrait = 607538,
                  desc = "One of many golems that staffed and operated the great titan vault, the Ancient Stone Keeper was part of a small group that served as an intermediary between the watchers left in control of the facility and their many servants. With the corruption of the Obsidian Sentinel, the Ancient Stone Keeper is the last of its kind, performing its duty by protecting the secrets of the titans as best it can until its inevitable shutdown.",
                  creatures = { { name = "Ancient Stone Keeper", display = 10798, dist = 4.7, eye = 0.78 } },
                  loot = { 9410, 47.7, 9411, 47 },
                  sections = {
                    { id = 4879, title = "Sand Storms", icon = 136022, text = "Ancient Stone Keeper summons a sand storm that moves towards a player, inflicting physical damage and reducing movement speed of all players within 5 yards." },
                  },
                },
                { id = 7291, name = "Galgann Firehammer", portrait = 607606,
                  desc = "Reacting to the discovery of Uldaman by Bronzebeard dwarves, the Dark Iron clan mounted an invasion of the vault to stop their ancestral foes from accessing the powerful artifacts within. Galgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation of Uldaman so that the emperor may harness the artifacts' destructive potential against the Dark Irons' enemies.",
                  creatures = { { name = "Galgann Firehammer", display = 6059, dist = 2.4, eye = 0.4 } },
                  loot = { 11311, 38.1, 9419, 19.9, 11310, 19.5, 9412, 17.7 },
                  sections = {
                    { id = 4880, title = "Fire Nova", icon = 135824, text = "Galgann Firehammer inflicts Fire damage to all players within 10 yards." },
                    { id = 4881, title = "Flame Lash", icon = 135807, text = "Galgann Firehammer burns a player, inflicting Fire damage and reducing their Fire resistance for 45 sec. This effect stacks up to 3 times." },
                    { id = 4882, title = "Amplify Flames", icon = 135807, text = "Galgann Firehammer increases the damage his current target takes from Fire for 30 sec." },
                    { id = 4883, title = "Shadowforge Geologist", display = 6056, dist = 2.4, eye = 0.4, text = "Shadowforge Geologists guard Galgann Firehammer and assist him in battle.", sub = {
                        { id = 4884, title = "Flame Spike", icon = 135826, flags = 64, text = "Shadowforge Geologist calls down a pillar of flame, inflicting Fire damage to all players within 5 yards of the targeted area and additional Fire damage every 3 seconds for 9 sec." },
                        { id = 4885, title = "Flame Lash", icon = 135807, flags = 64, text = "Shadowforge Geologist burns a player, inflicting Fire damage and reducing their Fire resistance for 45 sec. This effect stacks up to 3 times." },
                    } },
                  },
                },
                { id = 4854, name = "Grimlok", portrait = 607626,
                  desc = "In trogg society, the biggest, strongest, and most vicious trogg often becomes chieftain through displays of power. Grimlok is a comparative genius in that he has maintained control of the Stonevault troggs through intimidation and what might be considered crude psychological warfare. Having trained a deadly basilisk, Grimlok uses the threat of petrification by his beast to keep any would-be usurpers in line.",
                  creatures = { { name = "Grimlok", display = 11165, dist = 2.8, eye = 0.47 } },
                  loot = { 9415, 39.7, 9414, 28.8, 9416, 19.4, 7670, 0 },
                  sections = {
                    { id = 4886, title = "Chain Bolt", icon = 136015, flags = 64, text = "Grimlok strikes his target with a lightning bolt that arcs to nearby players, inflicting Nature damage to 3 targets." },
                    { id = 4887, title = "Lightning Bolt", icon = 136048, flags = 64, text = "Grimlok blasts his current target with lightning, inflicting Nature damage." },
                    { id = 4888, title = "Bloodlust", icon = 136012, flags = 128, text = "Grimlok increases one of his ally's attack speed by 30% for 30 sec." },
                    { id = 4889, title = "Shrink", icon = 136121, flags = 320, text = "Grimlok shrinks all players within 5 yards, reducing their Strength and Stamina for 2 min." },
                    { id = 4891, title = "Jadespine Basilisk", text = "Grimlok fights with the aid of his pet Jadespine Basilisk.", sub = {
                        { id = 4892, title = "Reflection", icon = 136222, flags = 128, text = "Jadespine Basilisk's skin shimmers, giving it a chance to reflect harmful spells back at the caster for 5 sec." },
                        { id = 4893, title = "Crystalline Slumber", icon = 136090, flags = 192, text = "Jadespine Basilisk inflicts Arcane damage to a player and stuns them for 15 sec." },
                    } },
                  },
                },
                { id = 2748, name = "Archaedas", portrait = 607546,
                  desc = "Deep within Uldaman is a chamber containing one of the greatest treasures of the titans, created by Norgannon himself. However, thus far no explorers have managed to gain access to the relic, for any attempt at doing so activates the great watcher Archaedas, an immense guardian who easily dispatches treasure seekers through his powerful attacks and a veritable army of servants. Crafted from some of the oldest, strongest stone taken from Uldaman's depths, Archaedas is a foe as formidable as he is ancient.",
                  creatures = { { name = "Archaedas", display = 5988, dist = 11.1, eye = 1.85 } },
                  loot = { 11118, 62.4, 9413, 13.6, 9418, 13.2 },
                  sections = {
                    { id = 4894, title = "Awaken Earthen Dwarf", icon = 254108, text = "Archaedas awakens an Earthen Custodian every 10 seconds to assist him in battle.", sub = {
                        { id = 4895, title = "Earthen Custodian", display = 6025, dist = 2.4, eye = 0.4, text = "Earthen Custodians aid Archaedas in battle." },
                    } },
                    { id = 4896, title = "Awaken Earthen Guardian", icon = 134400, text = "When Archaedas reaches 66% health remaining, he awakens the 6 Earthen Guardians.", sub = {
                        { id = 4897, title = "Earthen Guardian", display = 6026, dist = 2.4, eye = 0.4, sub = {
                            { id = 4898, title = "Whirlwind", icon = 132369, text = "Earthen Guardian whirlwinds, inflicting Physical damage to all enemies within 8 yards." },
                        } },
                    } },
                    { id = 4899, title = "Awaken Vault Warder", icon = 134400, text = "When Archaedas reaches 33% health remaining, he awakens the 2 Vault Warders.", sub = {
                        { id = 4900, title = "Vault Warder", display = 5989, dist = 4.7, eye = 0.78, sub = {
                            { id = 4901, title = "Trample", icon = 136063, text = "Vault Warders inflict Physical damage to all enemies within 10 yards." },
                        } },
                    } },
                    { id = 4902, title = "Ground Tremor", icon = 136025, text = "Archaedas shakes the ground, stunning all enemies within 20 yards." },
                  },
                },
              },
