            { id = 232, name = "Maraudon", continent = 1414, map = "Mara", floor = 1, area = 2100, button = 608209, lore = 608248, bg = 608170,
              desc = "According to legend, Zaetar, son of Cenarius, and the earth elemental princess Theradras begot the barbaric centaur race. Shortly after the centaur's creation, the ruthless creatures murdered their father. The grief-stricken Theradras is said to have trapped her lover's spirit within Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted elemental minions roam every corner of the sprawling caves.",
              encounters = {
                { id = 13282, name = "Noxxion", portrait = 607728,
                  desc = "Noxxion is a living embodiment of corruption. Theradras ordered her ally Lord Vyletongue to create this putrid elemental to be a powerful servant and a loyal pet to ease the princess's loneliness. Noxxion spreads its toxic essence into areas of Maraudon that have not yet withered under Theradras's malign influence.",
                  creatures = { { name = "Noxxion", display = 11172, dist = 4, eye = 1.03 } },
                  loot = { 17746, 36.2, 17744, 35.9, 17745, 17.5 },
                  sections = {
                    { id = 4709, title = "Toxic Volley", icon = 136016, flags = 512, text = "Noxxion unleashes a volley of toxin, inflicting Nature damage instantly to all players within 45 yards and additional Nature damage every 3 seconds for 15 sec." },
                    { id = 4710, title = "Uppercut", icon = 132939, text = "Noxxion uppercuts his current target, inflicting Physical damage and knocking them away." },
                    { id = 4711, title = "Summon Noxxion Spawn", icon = 136006, text = "Noxxion's body divides into 5 Noxxion Spawn, rendering him unable to fight for up to 20 seconds. Once all 5 Noxxion Spawn are killed, Noxxion regains his original form.", sub = {
                        { id = 4712, title = "Noxxion Spawn", display = 5492, dist = 4, eye = 1.03, text = "Noxxion Spawn split from Noxxion's main body." },
                    } },
                  },
                },
                { id = 12258, name = "Razorlash", portrait = 607756,
                  desc = "Razorlash was made to accompany Noxxion through Maraudon. In time, this new creation became one of the princess's most cherished servants. Razorlash constantly wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.",
                  creatures = { { name = "Razorlash", display = 12389, dist = 4.5, eye = 0.71 } },
                  loot = { 17749, 24.7, 17750, 24.2, 17748, 24, 17751, 23.8 },
                  sections = {
                    { id = 4713, title = "Puncture", icon = 132090, text = "Razorlash punctures its current target, inflicting Physical damage every 2 seconds for 10 sec." },
                    { id = 4714, title = "Thrash", icon = 132152, text = "Razorlash thrashes its current target, attacking two additional times." },
                    { id = 4715, title = "Cleave", icon = 132338, text = "Razorlash cleaves, inflicting Physical damage to its current target and their nearest allies." },
                  },
                },
                { id = 13601, name = "Tinkerer Gizlock", portrait = 607796,
                  desc = "Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. Their plan went horribly wrong when satyrs slaughtered everyone in the party save for Gizlock. The goblin, trapped within the caves and driven to the brink of madness, sees himself as the subterranean region's new ruler.",
                  creatures = { { name = "Tinkerer Gizlock", display = 7125, dist = 2.1, eye = 0.35 } },
                  loot = { 17719, 33.1, 17718, 32.8, 17717, 32.8 },
                  sections = {
                    { id = 4721, title = "Bomb", icon = 135826, text = "Tinkerer Gizlock throws a bomb at a random player, inflicting Fire damage to all players within 5 yards." },
                    { id = 4722, title = "Goblin Dragon Gun", icon = 135818, text = "Tinkerer Gizlock fires his Goblin Dragon Gun, inflicting 140 Fire damage to all players in front of him for 8 sec." },
                    { id = 4723, title = "Flash Bomb", icon = 136142, text = "Tinkerer Gizlock throws a flash bomb, causing all Beasts within 5 yards to flee." },
                    { id = 4724, title = "Shoot", icon = 132222, text = "Tinkerer Gizlock shoots a random player, inflicting Physical damage." },
                  },
                },
                { id = 12236, name = "Lord Vyletongue", portrait = 607699,
                  desc = "The satyr lord Vyletongue journeyed into Maraudon's depths after hearing of its corruption. Theradras was wary of the conniving demon at first, but Vyletongue proved his worth by creating an array of wretched minions, such as Noxxion and Razorlash, for the princess.",
                  creatures = { { name = "Lord Vyletongue", display = 12334, dist = 4.2, eye = 0.69 } },
                  loot = { 17754, 29.3, 17752, 28.4, 17755, 27 },
                  sections = {
                    { id = 4730, title = "Shoot", icon = 132222, text = "Lord Vyletongue shoots a random player, inflicting Physical damage." },
                    { id = 4731, title = "Multi-Shot", icon = 132330, text = "Lord Vyletongue fires a volley of missiles at a random player, inflicting Arcane damage to them and their nearby allies, affecting up to 5 targets." },
                    { id = 4732, title = "Blink", icon = 135736, text = "Lord Vyletongue teleports 20 yards forward." },
                    { id = 4733, title = "Smoke Bomb", icon = 132156, flags = 128, text = "Lord Vyletongue throws a smoke bomb, stunning all players within 5 yards." },
                  },
                },
                { id = 12225, name = "Celebras the Cursed", portrait = 607562,
                  desc = "Upon learning of his uncle's tragic fate, the noble Celebras swore to free Zaetar's spirit. Yet the keeper of the grove was not prepared for the horrors that awaited him in Maraudon's shadowy corridors. The dark energies permeating the area quickly overcame Celebras, filling his heart with uncontrollable rage.",
                  creatures = { { name = "Celebras the Cursed", display = 12350, dist = 6.2, eye = 1.03 } },
                  loot = { 17738, 32.5, 17739, 32.3, 17740, 29.8 },
                  sections = {
                    { id = 4745, title = "Corrupt Force of Nature", icon = 136036, text = "Celebras the Cursed summons 3 Corrupt Forces of Nature to aid him in battle for 1 min.", sub = {
                        { id = 6459, title = "Corrupt Force of Nature", display = 9593, dist = 5, eye = 0.84, text = "Corrupt Forces of Nature defend Celebras the Cursed in battle." },
                    } },
                    { id = 4746, title = "Twisted Tranquility", icon = 136107, text = "Celebras the Cursed inflicts Nature damage to all players within 45 yards, reducing their movement speed by 70% and increasing the time between their attacks by 300%." },
                    { id = 4747, title = "Wrath", icon = 136006, flags = 64, text = "Celebras the Cursed hurls a bolt of energy at his current target, inflicting Nature damage." },
                    { id = 4748, title = "Entangling Roots", icon = 136100, flags = 64, text = "Celebras the Cursed entangles his current target, immobilizing them and inflicting Nature damage every 3 seconds for 10 sec." },
                  },
                },
                { id = 12203, name = "Landslide", portrait = 607684,
                  desc = "For years, the ancient mountain giant known as Landslide cultivated brilliant crystal gardens in Maraudon, but Theradras enthralled the behemoth when she took up residence there. This once-stoic giant now lives only to serve his tyrannical new master.",
                  creatures = { { name = "Landslide", display = 12293, dist = 11.5, eye = 1.92 } },
                  loot = { 17943, 26, 17737, 24.5, 17736, 23.8, 17734, 22.4 },
                  sections = {
                    { id = 4749, title = "Knock Away", icon = 132939, text = "Landslide inflicts Physical damage to his current target, knocking them back." },
                    { id = 4751, title = "Trample", icon = 136063, text = "Landslide tramples all players within 10 yards, inflicting Physical damage." },
                    { id = 4750, title = "Landslide", icon = 136025, text = "Landslide stuns all players within 100 yards for 8 sec and summons a Theradrim Shardling every 2 seconds.", sub = {
                        { id = 6460, title = "Theradrim Shardling", display = 12310, dist = 13.8, eye = 2.22, sub = {
                            { id = 6461, title = "Strike", icon = 132282, text = "Theradrim Shardlings strike players, inflicting Physical damage." },
                        } },
                    } },
                  },
                },
                { id = 13596, name = "Rotgrip", portrait = 607761,
                  desc = "Rumor has it that Rotgrip has dwelled in Maraudon's subterranean waters for millennia. The famed dwarven hunter Hemet Nesingwary once proclaimed that the beast could not be found, and a number of amateur trackers accepted the challenge of seeking out the legendary creature. None of them ever returned.",
                  creatures = { { name = "Rotgrip", display = 13589, dist = 5.8, eye = 0.4 } },
