            { id = 241, name = "Zul'Farrak", continent = 1414, map = "ZF", floor = 1, area = 1176, button = 608230, lore = 608267, bg = 608191,
              desc = "Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated group was forced to surrender much of its territory throughout history. Now, it appears that Zul'Farrak's inhabitants are creating a horrific army of undead trolls to conquer the surrounding region. Other disturbing rumors tell of an ancient creature sleeping within the city--one that, if awakened, will rain death and destruction across Tanaris.",
              encounters = {
                { id = 7272, name = "Theka the Martyr", portrait = 607793,
                  desc = "Long ago, the martyr Theka was slain in the brutal war between the qiraji and the trolls. Zul'Farrak still stands because of his brave sacrifice. Even in death he maintains a vigil over his beloved city, and it is said that the dozens of insectoid warriors who killed him were cursed to live as mindless scarabs, scuttling at the martyr's side.",
                  creatures = { { name = "Theka the Martyr", display = 6696, dist = 4, eye = 0.66 } },
                  loot = { 10660, 43.7 },
                  sections = {
