                    { id = 29864, title = "Curse of the Martyr", icon = 134933, flags = 35, text = "Theka curses a random target, transforming them into a scarab and sounding the toll of persecution which draws the attention of nearby scarabs." },
                  },
                },
                { id = 7795, name = "Hydromancer Velratha", portrait = 607652,
                  desc = "Unlike most of the Sandfury trolls, Hydromancer Velratha has traveled the world, collecting knowledge and artifacts to help her command Zul'Farrak's sacred waters. Although the hydromancer's actions have earned her many enemies abroad, she sees the incredible power at her command as justification for her past misdeeds.",
