                { id = 9499, name = "Plugger Spazzring", portrait = 607741,
                  desc = "They say that at the Grim Guzzler everyone knows your name. This sense of camaraderie is due to the hard work of Spazzring, a leper gnome who sought a new life in Blackrock Depths after the fall of Gnomeregan. Despite his history of dabbling with evil as a warlock, he takes pride in his job as the tavern's barkeep, making sure that his patrons' mugs never run dry.",
                  creatures = { { name = "Plugger Spazzring", display = 8652, dist = 1.6, eye = 0.27 } },
                  loot = { 11735, 0, 18043, 0, 22275, 0, 18044, 0, 18592, 0, 11612, 0, 2662, 0, 2663, 0, 11742, 0, 12793, 0, 12791, 0, 18653, 0, 13483, 0, 15759, 0, 11325, 0, 11602, 0 },
                  sections = {
                    { id = 4485, title = "Owner of the Grim Guzzler", flags = 32, text = "Plugger Spazzring carries the Key to the Grim Guzzler. If players pick Plugger Spazzring's pockets he will alert all of his patrons to attack players. This changes all of the Grim Guzzler's patrons from neutral to aggressive." },
                    { id = 4486, title = "Shadowbolt", icon = 136197, text = "Plugger Spazzring inflicts Shadow damage to a player." },
                    { id = 4487, title = "Immolate", icon = 135817, flags = 128, text = "Plugger Spazzring inflicts Fire damage to a player. Immolate continues burning that player for Fire damage every 3 seconds for 21 sec." },
                    { id = 4488, title = "Demon Armor", icon = 136185, flags = 128, text = "Plugger Spazzring is protected by demonic energies. Demon Armor increases Plugger Spazzring's armor, Shadow resistance, and health regeneration." },
