            { id = 237, name = "The Temple of Atal'hakkar", continent = 1415, map = "ST", floor = 1, area = 1477, button = 608217, lore = 608256, bg = 608178,
              desc = "Thousands of years ago, the Gurubashi empire was plunged into a civil war by a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people exiled the Atal'ai to the Swamp of Sorrows, where the priests built the Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the temple beneath the swamp and assigned wardens to ensure that the summoning rituals never be performed again.",
              encounters = {
                { id = 8443, name = "Avatar of Hakkar", portrait = 607548,
                  desc = "Hakkar was notorious for demanding sacrifices from his followers. Many millennia ago, he instructed the Atal'ai to bring forth his avatar, using blood ritually drained from living victims to feed him. The Atal'ai priests now seek to raise Hakkar's avatar with a modified version of this ritual, one that involves sacrificing green dragons. If the Atal'ai succeed, the re-emergence of Hakkar's avatar could spell doom for Azeroth.",
                  creatures = { { name = "Avatar of Hakkar", display = 8053, dist = 10.3, eye = 1.46 } },
                  loot = { 10842, 30.3, 10846, 30.2, 10843, 28.5, 10845, 26.5, 10838, 14.3, 10844, 14.1, 12462, 0 },
                  sections = {
                    { id = 4903, title = "Cause Insanity", icon = 136206, text = "The Avatar of Hakkar drives a player insane, causing them to attack their own allies for 6 sec. Players driven insane will attack 50% faster and move 80% faster." },
                    { id = 4904, title = "Curse of Tongues", icon = 136140, flags = 256, text = "The Avatar of Hakkar curses a player, reducing their casting speed by 50% for 15 sec." },
                    { id = 4905, title = "Lash", icon = 132109, text = "The Avatar of Hakkar lashes out at his current target, stunning them for 2 sec. In addition, Lash has a 10% chance of disarming its target." },
                  },
                },
                { id = 5710, name = "Jammal'an the Prophet", portrait = 607665,
                  desc = "Jammal'an is the current leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar. While in deep meditation, Jammal'an received instructions on how to resurrect Hakkar by using the blood of his draconic foes, the green dragonflight. Jammal'an and his undead bodyguard Ogom the Wretched stand ready to oppose any who would prevent Hakkar's return, though the prophet's actions may unleash upon Azeroth an even more terrible force: the Emerald Nightmare.",
                  creatures = { { name = "Jammal'an the Prophet", display = 6708, dist = 4, eye = 0.66 } },
                  loot = { 10808, 29.6, 10807, 27.2, 10806, 27 },
                  sections = {
                    { id = 4934, title = "Healing Wave", icon = 136052, text = "Jammal'an the Prophet heals an ally." },
                    { id = 4935, title = "Flamestrike", icon = 135826, text = "Jammal'an the Prophet calls down a pillar of flame, inflicting Fire damage to all players within 5 yards of the targeted area and additional Fire damage every 2 seconds for 8 sec." },
                    { id = 4936, title = "Earthgrab Totem", icon = 136064, text = "Jammal'an the Prophet summons an Earthgrab Totem at his feet for 30 sec. Earthgrab Totem immobilizes all players within 10 yards every 5 seconds." },
                    { id = 4937, title = "Hex of Jammal'an", icon = 136232, text = "Jammal'an the Prophet hexes a player, increasing their damage by 400%, transforming them and causing them to attack their allies." },
                    { id = 4938, title = "Ogom the Wretched", display = 6709, dist = 4, eye = 0.66, text = "Ogom the Wretched joins Jammal'an the Prophet in battle.", sub = {
                        { id = 4939, title = "Curse of Weakness", icon = 136138, flags = 256, text = "Ogom the Wretched curses a player, reducing their Physical damage done." },
                        { id = 4940, title = "Shadow Word: Pain", icon = 136207, flags = 128, text = "Ogom the Wretched utters a word of darkness, inflicting Shadow damage to a player every 3 seconds for 18 sec." },
                        { id = 4941, title = "Shadow Bolt", icon = 136197, flags = 64, text = "Ogom the Wretched hurls a bolt of dark magic at a player, inflicting Shadow damage." },
                    } },
                  },
                },
                { id = 5312, name = "Wardens of the Dream", portrait = 608311,
                  desc = "Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.",
                  creatures = { { name = "Wardens of the Dream", display = 7553, dist = 24.5, eye = 2.88 } },
                  sections = {
                    { id = 6114, title = "The Wardens of the Dream", text = "Dreamscythe, Weaver, Morphaz and Hazzas defend the Shade of Eranikus with their lives.", sub = {
                        { id = 4942, title = "Acid Breath", icon = 136007, text = "The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage every 5 seconds for 45 sec to all players in front of them." },
                        { id = 4943, title = "Wing Flap", icon = 136022, text = "The Wardens of the Dream thrash their wings, knocking all players in front of them backwards." },
                    } },
                  },
                },
                { id = 5709, name = "Shade of Eranikus", portrait = 607768,
                  desc = "Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.",
